def end_desktop(self, sid: str, reason: str) -> None:
    self._reset_gui_state(sid, reason)
    if self.desktop.lease(sid):
        try:
            self.handback(sid, None, reason)
        except ServiceError:
            pass
    self.desktop.close_all(sid)
